import{_ as l,a0 as p,w as o,s as d,ao as r,I as n,x as i,a1 as a,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在終端中顯示圖片 | LCTT x X-CMD","titleTemplate":false,"description":"如何在終端中顯示圖片 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在終端中顯示圖片 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在終端中顯示圖片 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180510 How To Display Images In The Terminal","title":"如何在終端中顯示圖片","tag":"201805","desc":""},"relativePath":"201805/20180510 How To Display Images In The Terminal.md","filePath":"[post].md"}'),g={name:"201805/20180510 How To Display Images In The Terminal.md"};function h(c,s,u,k,f,b){const e=p("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="如何在終端中顯示圖片" tabindex="-1">如何在終端中顯示圖片 <a class="header-anchor" href="#如何在終端中顯示圖片" aria-label="Permalink to “如何在終端中顯示圖片”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/05/fim-2-720x340.png" alt=""></p><p>Linux 上有許多 GUI 圖片瀏覽器。但我尚未聽説或使用過任何在終端中顯示圖片的應用程序。幸運的是，我剛剛發現了一個可用於在終端中顯示圖像的名叫 <strong>FIM</strong> 的圖像查看器。FIM 引起了我的注意，是因為與大多數 GUI 圖片瀏覽器相比，它非常輕巧。毫不遲疑，讓我們來看看它能做什麼。</p><h3 id="使用-fim-在終端中顯示圖像" tabindex="-1">使用 FIM 在終端中顯示圖像 <a class="header-anchor" href="#使用-fim-在終端中顯示圖像" aria-label="Permalink to “使用 FIM 在終端中顯示圖像”">​</a></h3><p><strong>FIM</strong> 意即 <strong>F</strong>bi <strong>IM</strong>proved。對於那些不知道的人，<strong>Fbi</strong> 是指 Linux 中的 <strong>f</strong>rame <strong>b</strong>uffer <strong>i</strong>mageviewer。它使用系統的幀緩衝器直接從命令列顯示圖像。默認情況下，它能用終端顯示 bmp、gif、jpeg、PhotoCD、png、ppm、tiff 和 xwd。對於其他格式，它會嘗試使用 ImageMagick 的轉換。</p><p>FIM 基於 Fbi，它是一款高度可高度定製及腳本化的圖像瀏覽器，非常適合使用 Vim 文本編輯器或 Mutt 等軟件的用户。它會以全屏顯示圖像，並可通過鍵盤快捷鍵控制（如調整大小、翻轉、縮放）。與 Fbi 不同的是，FIM 是通用的：它可以打開許多文件格式，並且可以在以下視頻模式下顯示圖片：</p><ul><li>使用 Linux framebuffer 設備，以圖形方式呈現</li><li>在 X / Xorg 下，使用 SDL 庫，以圖形方式呈現</li><li>在 X / Xorg 下，使用 Imlib2 庫，以圖形方式呈現。</li><li>在任何文本控制台中使用 AAlib 庫呈現為 ASCII 字符畫</li></ul><p>FIM 是完全免費且開源的。</p><h3 id="安裝-fim" tabindex="-1">安裝 FIM <a class="header-anchor" href="#安裝-fim" aria-label="Permalink to “安裝 FIM”">​</a></h3><p>基於 DEB 的系統，如 Ubuntu、Linux Mint， 可從默認的倉庫中獲取 FIM 圖像查看器。因此，你可以使用如下命令安裝fbi：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install fim</span></span></code></pre></div><p>如果它在你使用的 Linux 發行版的倉庫中不包含 FIM，則可以下載源代碼進行編譯和安裝，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wget http://download.savannah.nongnu.org/releases/fbi-improved/fim-0.6-trunk.tar.gz</span></span>
<span class="line"><span>wget http://download.savannah.nongnu.org/releases/fbi-improved/fim-0.6-trunk.tar.gz.sig</span></span>
<span class="line"><span>gpg --search &#39;dezperado autistici org&#39;</span></span>
<span class="line"><span>＃按照屏幕上的説明，從密鑰服務器導入密鑰</span></span>
<span class="line"><span>gpg --verify fim-0.6-trunk.tar.gz.sig</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tar xzf fim-0.6-trunk.tar.gz</span></span>
<span class="line"><span>cd fim-0.6-trunk</span></span>
<span class="line"><span>./configure --help=short</span></span>
<span class="line"><span>＃閲讀./configure --help=short 的輸出：你可以在 ./configure 中添加選項</span></span>
<span class="line"><span>./configure</span></span>
<span class="line"><span>make</span></span>
<span class="line"><span>su -c“make install”</span></span></code></pre></div><h3 id="fim用法" tabindex="-1">FIM用法 <a class="header-anchor" href="#fim用法" aria-label="Permalink to “FIM用法”">​</a></h3><p>安裝完成後，您可以使用以下命令以“自動縮放”顯示的圖像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fim -a dog.jpg</span></span></code></pre></div><p>這裏是我的 Ubuntu 主機的示例輸出。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/05/fim-1.png" alt=""></p><p>正如你在上面的屏幕截圖中看到的，FIM 沒有使用任何外部 GUI 圖片瀏覽器。相反，它使用我們系統的幀緩衝器來顯示圖像。</p><p>如果當前目錄中有多個 .jpg 文件，可以使用通配符打開所有文件，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fim -a * .jpg</span></span></code></pre></div><p>要打開目錄中的所有圖像，例如 <code>Pictures</code>，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fim Pictures/</span></span></code></pre></div><p>我們也可以在文件夾及其子文件夾中遞歸地打開圖像，然後像下面那樣對列表進行排序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fim -R Pictures/ --sort</span></span></code></pre></div><p>要以 ASCII 格式渲染圖像，可以使用 <code>-t</code> 標誌。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fim -t dog.jpg</span></span></code></pre></div><p>要退出 Fim，請按 <code>ESC</code> 或 <code>q</code>。</p><h4 id="鍵盤快捷鍵" tabindex="-1">鍵盤快捷鍵 <a class="header-anchor" href="#鍵盤快捷鍵" aria-label="Permalink to “鍵盤快捷鍵”">​</a></h4><p>您可以使用各種鍵盤快捷鍵來管理圖像。例如，要加載下一張圖像和之前的圖像，請按下 <code>PgUp</code> / <code>PgDown</code> 鍵。成倍放大或縮小，請使用 <code>+</code> / <code>-</code> 鍵。以下是用於在FIM中控制圖像的常用按鍵。</p><ul><li><code>PageUp</code> / <code>Down</code>：上一張/下一張圖片</li><li><code>+</code> / <code>-</code> ：放大/縮小</li><li><code>a</code>：自動縮放</li><li><code>w</code>：自適應寬度</li><li><code>h</code>：自適應高度</li><li><code>j</code> / <code>k</code>：平移/向上</li><li><code>f</code> / <code>m</code>：翻轉/鏡像</li><li><code>r</code> / <code>R</code>：旋轉（順時針/逆時針）</li><li><code>ESC</code> / <code>q</code>：退出</li></ul><p>有關完整詳細信息，請參閲手冊頁。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man fim</span></span></code></pre></div><p>那麼，就是這樣。希望這對你有所幫助。後續還會介紹更多的優秀工具。敬請關注！</p><p>乾杯!</p><hr>`,37)),n("p",null,[s[1]||(s[1]=i("via: ",-1)),a(e,{href:"https://www.ostechnix.com/how-to-display-images-in-the-terminal/"},{default:t(()=>[...s[0]||(s[0]=[i("https://www.ostechnix.com/how-to-display-images-in-the-terminal/",-1)])]),_:1})]),n("p",null,[s[6]||(s[6]=i("作者：[SK] ",-1)),a(e,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...s[2]||(s[2]=[i("A",-1)])]),_:1}),s[7]||(s[7]=i(" 選題：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[i("lujun9972",-1)])]),_:1}),s[8]||(s[8]=i(" 譯者：",-1)),a(e,{href:"https://github.com/KevinSJ"},{default:t(()=>[...s[4]||(s[4]=[i("KevinSJ",-1)])]),_:1}),s[9]||(s[9]=i(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[i("wxy",-1)])]),_:1})]),n("p",null,[s[12]||(s[12]=i("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[i("LCTT",-1)])]),_:1}),s[13]||(s[13]=i(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[i("Linux中國",-1)])]),_:1}),s[14]||(s[14]=i(" 榮譽推出",-1))])])}const I=l(g,[["render",h]]);export{C as __pageData,I as default};
